package nir.com.neonvegasslots;
import static org.junit.Assert.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import android.content.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34) public class PurchaseDeliveryTest {
 SharedPreferences prefs;PurchaseDelivery delivery;static class Wallet implements PurchaseDelivery.Game {long coins=500;int energy=10;public String snapshot(){return coins+":"+energy;}public void grant(long c,int e){coins+=c;energy+=e;}public void restore(String s){String[] a=s.split(":");coins=Long.parseLong(a[0]);energy=Integer.parseInt(a[1]);}}
 @Before public void init(){prefs=RuntimeEnvironment.getApplication().getSharedPreferences("purchase_delivery_test",0);prefs.edit().clear().commit();delivery=new PurchaseDelivery(prefs,"state");}
 @Test public void grantAndReceiptSavedTogetherBeforeConsumePermission(){Wallet w=new Wallet();assertTrue(delivery.deliver("test-token-a","coins_small",1000,0,w));assertEquals(1500,w.coins);assertEquals("1500:10",prefs.getString("state",""));assertEquals("coins_small",prefs.getString(PurchaseDelivery.receipt("test-token-a"),""));}
 @Test public void repeatedCallbackAndProcessRecreationNeverGrantTwice(){Wallet w=new Wallet();assertTrue(delivery.deliver("test-token-b","energy_bundle",3000,200,w));assertTrue(delivery.deliver("test-token-b","energy_bundle",3000,200,w));assertEquals(3500,w.coins);Wallet reopened=new Wallet();reopened.restore(prefs.getString("state",""));assertTrue(new PurchaseDelivery(prefs,"state").deliver("test-token-b","energy_bundle",3000,200,reopened));assertEquals(3500,reopened.coins);assertEquals(210,reopened.energy);}
 @Test public void differentTokensGrantSeparately(){Wallet w=new Wallet();assertTrue(delivery.deliver("test-token-c","coins_small",1000,0,w));assertTrue(delivery.deliver("test-token-d","coins_small",1000,0,w));assertEquals(2500,w.coins);}
 @Test public void failedCommitRollsBackAndWithholdsConsumePermission()throws Exception{SharedPreferences broken=(SharedPreferences)java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{SharedPreferences.class},(proxy,method,args)->{if(method.getName().equals("edit")){SharedPreferences.Editor real=prefs.edit();return java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{SharedPreferences.Editor.class},(ep,em,ea)->{if(em.getName().equals("commit"))return false;Object result=em.invoke(real,ea);return result instanceof SharedPreferences.Editor?ep:result;});}return method.invoke(prefs,args);});PurchaseDelivery bad=new PurchaseDelivery(broken,"state");Wallet w=new Wallet();assertFalse(bad.deliver("test-token-fail","coins_small",1000,0,w));assertEquals(500,w.coins);assertTrue(bad.blocked());assertFalse(prefs.contains("state"));assertFalse(bad.deliver("test-token-next","coins_small",1000,0,w));}
 @Test public void receiptProductMismatchWithholdsConsumePermission(){Wallet w=new Wallet();assertTrue(delivery.deliver("test-token-conflict","coins_small",1000,0,w));assertFalse(delivery.deliver("test-token-conflict","coins_mega",30000,0,w));assertEquals(1500,w.coins);}
 @Test public void actualGameSnapshotRestoresCreditedPurchaseWithoutSecondGrant(){SlotsView v=new SlotsView(RuntimeEnvironment.getApplication());PurchaseDelivery.Game game=new PurchaseDelivery.Game(){public String snapshot(){return v.serialize();}public void grant(long c,int e){v.grantPurchaseUnchecked(c,e);}public void restore(String s){v.restore(s);}};String before=game.snapshot();assertTrue(delivery.deliver("test-actual","coins_small",1000,0,game));String after=game.snapshot();assertNotEquals(before,after);SlotsView reopened=new SlotsView(RuntimeEnvironment.getApplication());reopened.restore(prefs.getString("state",""));assertEquals(after,reopened.serialize());assertTrue(delivery.deliver("test-actual","coins_small",1000,0,game));assertEquals(after,game.snapshot());}
 @Test public void invalidTokenDoesNotAuthorizeConsumption(){Wallet w=new Wallet();assertFalse(delivery.deliver("","coins_small",1000,0,w));assertEquals(500,w.coins);assertFalse(prefs.contains("state"));}
}
